class Solution:
    def shortestCommonSupersequence(self, str1, str2):
        from functools import lru_cache
        def choose(a, b):
            return a if len(a) <= len(b) else b
        @lru_cache(None)
        def dfs(i, j):
            if i == len(str1):
                return str2[j:]
            if j == len(str2):
                return str1[i:]
            if str1[i] == str2[j]:
                return str1[i] + dfs(i + 1, j + 1)
            return choose(str1[i] + dfs(i + 1, j), str2[j] + dfs(i, j + 1))
        return dfs(0, 0)

